(function() {
    'use strict';

    class TurnAroundAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'TurnAround: Restructuring & Distressed Company Management';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    name: 'Crisis Stabilization',
                    nameEs: 'Estabilización de Crisis',
                    days: 'Days 1-30',
                    daysEs: 'Días 1-30',
                    briefing: '<strong>Day 1 — You arrive at Ferrovia Industrial Group.</strong><br><br>Ferrovia is a 60-year-old Brazilian manufacturer of rail components. The situation is dire:<br>• €180M total debt (€120M secured bank loans, €60M unsecured bonds)<br>• €15M cash remaining, burning €5M/month<br>• Annual EBITDA: -€8M (operating at a loss)<br>• Altman Z-Score: 1.10 (deep distress zone)<br>• Three facilities, 1,200 employees, primary customer VALE (70% of revenue)<br><br>Your first 30 days: <strong>stop the bleeding</strong>. Cut overhead, optimize working capital, sell non-core assets, and reduce payroll. Every euro saved extends the runway.',
                    briefingEs: '<strong>Día 1 — Llegas a Ferrovia Industrial Group.</strong><br><br>Ferrovia es un fabricante brasileño de componentes ferroviarios con 60 años de historia. La situación es crítica:<br>• €180M de deuda total (€120M préstamos bancarios garantizados, €60M bonos sin garantía)<br>• €15M en efectivo, quemando €5M/mes<br>• EBITDA anual: -€8M (operando con pérdidas)<br>• Altman Z-Score: 1.10 (zona de alto riesgo)<br>• Tres instalaciones, 1.200 empleados, cliente principal VALE (70% de ingresos)<br><br>Tus primeros 30 días: <strong>detener la hemorragia</strong>. Recorta gastos, optimiza capital de trabajo, vende activos no esenciales y reduce nómina.'
                },
                {
                    name: 'Creditor Negotiation',
                    nameEs: 'Negociación con Acreedores',
                    days: 'Days 31-60',
                    daysEs: 'Días 31-60',
                    briefing: '<strong>Day 31 — Creditors are calling.</strong><br><br>Bank A (€80M secured) and Bank B (€40M secured) want answers. Bondholders (€60M unsecured) are nervous. You must present a restructuring proposal:<br>• How much of a haircut will unsecured creditors accept?<br>• Do you need DIP financing to bridge the restructuring?<br>• Should you file Chapter 11 (court protection, expensive, public) or negotiate out-of-court (faster, private, but needs consensus)?<br>• How long a maturity extension do you need?<br><br>Remember: creditors prefer a restructured company to a liquidated one — but only if the plan is credible.',
                    briefingEs: '<strong>Día 31 — Los acreedores están llamando.</strong><br><br>El Banco A (€80M garantizados) y el Banco B (€40M garantizados) quieren respuestas. Los bonistas (€60M sin garantía) están nerviosos. Debes presentar una propuesta de reestructuración:<br>• ¿Qué porcentaje de quita aceptarán los acreedores no garantizados?<br>• ¿Necesitas financiamiento DIP para cubrir la reestructuración?<br>• ¿Deberías solicitar Chapter 11 (protección judicial, costoso, público) o negociar extrajudicialmente (más rápido, privado, pero requiere consenso)?<br>• ¿Cuánta extensión de vencimiento necesitas?<br><br>Recuerda: los acreedores prefieren una empresa reestructurada a una liquidada — pero solo si el plan es creíble.'
                },
                {
                    name: 'Operational Triage',
                    nameEs: 'Triaje Operativo',
                    days: 'Days 61-80',
                    daysEs: 'Días 61-80',
                    briefing: '<strong>Day 61 — Time to restructure operations.</strong><br><br>Ferrovia has three operating segments:<br>• <strong>Wheels & Axles (core)</strong>: €32M revenue, 8% margin, serves VALE<br>• <strong>Other Components</strong>: €8M revenue, -2% margin, non-core<br>• <strong>Minas Gerais Plant</strong>: €5M revenue, 2% margin, redundant capacity<br><br>You must decide: which facilities to close, whether to divest non-core divisions, how deep to cut the workforce, and whether to invest in core operations efficiency. Each decision has cascading consequences for revenue, costs, morale, and VALE confidence.',
                    briefingEs: '<strong>Día 61 — Es hora de reestructurar operaciones.</strong><br><br>Ferrovia tiene tres segmentos operativos:<br>• <strong>Ruedas y Ejes (core)</strong>: €32M ingresos, 8% margen, sirve a VALE<br>• <strong>Otros Componentes</strong>: €8M ingresos, -2% margen, no esencial<br>• <strong>Planta Minas Gerais</strong>: €5M ingresos, 2% margen, capacidad redundante<br><br>Debes decidir: qué instalaciones cerrar, si desinvertir divisiones no esenciales, cuánto recortar la plantilla e invertir en eficiencia de operaciones core.'
                },
                {
                    name: 'Viability & Refinancing',
                    nameEs: 'Viabilidad y Refinanciamiento',
                    days: 'Days 81-90',
                    daysEs: 'Días 81-90',
                    briefing: '<strong>Day 81 — Present your plan to stakeholders.</strong><br><br>The restructuring actions are in motion. Now you must convince creditors and the board that the company is viable long-term:<br>• Set a target debt level post-restructuring<br>• Commit to an EBITDA target that creditors will believe<br>• Choose your communication strategy with stakeholders<br><br>Your credibility depends on what you achieved in Rounds 1-3. Overpromise and creditors will see through it. Underpromise and they may push for liquidation.',
                    briefingEs: '<strong>Día 81 — Presenta tu plan a los stakeholders.</strong><br><br>Las acciones de reestructuración están en marcha. Ahora debes convencer a los acreedores y al directorio de que la empresa es viable a largo plazo:<br>• Establece un nivel objetivo de deuda post-reestructuración<br>• Compromete un objetivo de EBITDA que los acreedores crean<br>• Elige tu estrategia de comunicación con los stakeholders<br><br>Tu credibilidad depende de lo que lograste en las Rondas 1-3.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 15,
                    monthlyBurn: 5.0,
                    totalDebt: 180,
                    securedDebt: 120,
                    unsecuredDebt: 60,
                    ebitda: -8,
                    zScore: 1.10,
                    cashRunway: 90,
                    valeConfidence: 65,
                    morale: 40,
                    employees: 1200,
                    revenue: 45,
                    overheadCosts: 24,
                    assetValue: 50,
                    dipFinancing: 0,
                    haircutAccepted: 0,
                    restructuringPath: 'none',
                    minasOpen: true,
                    componentsOwned: true,
                    cashHistory: [],
                    zScoreHistory: [],
                    ebitdaHistory: [],
                    burnHistory: [],
                    roundActions: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    overheadCut: 15,
                    workingCapitalEffort: 50,
                    assetSalesTarget: 5,
                    payrollCut: 10,
                    haircutProposal: 30,
                    dipAmount: 15,
                    restrPath: 'out-of-court',
                    maturityExtension: 24,
                    closeMinas: 1,
                    divestComponents: 1,
                    workforceReduction: 15,
                    capexInvestment: 2,
                    refinancingTarget: 100,
                    ebitdaCommitment: 10,
                    commStrategy: 'transparent'
                };
            }
            this._updateBriefing(state);
            this._buildDecisionInputs(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var lang = (window.mySimulation && (window.mySimulation.language || window.mySimulation.currentLanguage)) || (typeof document !== 'undefined' && document.documentElement && document.documentElement.lang) || 'en';
            var isEs = lang === 'es';

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = isEs ? round.briefingEs : round.briefing;

            var roundNameEl = document.getElementById('roundNameDisplay');
            if (roundNameEl) {
                var rName = isEs ? round.nameEs : round.name;
                var rDays = isEs ? round.daysEs : round.days;
                roundNameEl.innerHTML = rName + ' (' + rDays + ')';
            }
        }

        _buildDecisionInputs(state) {
            var panel = document.getElementById('decisionInputs');
            if (!panel) return;
            var period = state.currentPeriod || 1;
            var d = state.decisions;
            var html = '';

            if (period === 1) {
                html += this._sliderGroup('overheadCut', 'overhead_cut_label', 'overhead_cut_hint', d.overheadCut || 15, 0, 40, '%');
                html += this._sliderGroup('workingCapitalEffort', 'wc_effort_label', 'wc_effort_hint', d.workingCapitalEffort || 50, 0, 100, '%');
                html += this._numberGroup('assetSalesTarget', 'asset_sales_label', 'asset_sales_hint', d.assetSalesTarget || 5, 0, 25);
                html += this._sliderGroup('payrollCut', 'payroll_cut_label', 'payroll_cut_hint', d.payrollCut || 10, 0, 30, '%');
            } else if (period === 2) {
                html += this._sliderGroup('haircutProposal', 'haircut_label', 'haircut_hint', d.haircutProposal || 30, 0, 60, '%');
                html += this._numberGroup('dipAmount', 'dip_label', 'dip_hint', d.dipAmount || 15, 5, 25);
                html += this._selectGroup('restrPath', 'restr_path_label', 'restr_path_hint', d.restrPath || 'out-of-court', [
                    { value: 'out-of-court', labelKey: 'opt_out_of_court' },
                    { value: 'chapter11', labelKey: 'opt_chapter11' }
                ]);
                html += this._sliderGroup('maturityExtension', 'maturity_label', 'maturity_hint', d.maturityExtension || 24, 6, 36, ' mo');
            } else if (period === 3) {
                html += this._selectGroup('closeMinas', 'close_minas_label', 'close_minas_hint', 1, [
                    { value: 1, labelKey: 'opt_yes' },
                    { value: 0, labelKey: 'opt_no' }
                ]);
                html += this._selectGroup('divestComponents', 'divest_label', 'divest_hint', 1, [
                    { value: 1, labelKey: 'opt_yes' },
                    { value: 0, labelKey: 'opt_no' }
                ]);
                html += this._sliderGroup('workforceReduction', 'workforce_label', 'workforce_hint', d.workforceReduction || 15, 0, 40, '%');
                html += this._numberGroup('capexInvestment', 'capex_label', 'capex_hint', d.capexInvestment || 2, 0, 5);
            } else if (period === 4) {
                html += this._numberGroup('refinancingTarget', 'refinancing_label', 'refinancing_hint', d.refinancingTarget || 100, 50, 150);
                html += this._numberGroup('ebitdaCommitment', 'ebitda_commit_label', 'ebitda_commit_hint', d.ebitdaCommitment || 10, 2, 25);
                html += this._selectGroup('commStrategy', 'comm_strategy_label', 'comm_strategy_hint', d.commStrategy || 'transparent', [
                    { value: 'transparent', labelKey: 'opt_transparent' },
                    { value: 'optimistic', labelKey: 'opt_optimistic' },
                    { value: 'conservative', labelKey: 'opt_conservative' }
                ]);
            }
            panel.innerHTML = html;
            this._attachSliderListeners();
        }

        _sliderGroup(id, labelKey, hintKey, val, min, max, unit) {
            return '<div class="turnaround-sim-decision-group">' +
                '<label for="' + id + 'Input" data-i18n="' + labelKey + '"></label>' +
                '<input type="range" id="' + id + 'Input" min="' + min + '" max="' + max + '" value="' + val + '" step="1">' +
                '<span class="turnaround-sim-range-display" id="' + id + 'Display">' + val + unit + '</span>' +
                '<div class="turnaround-sim-hint" data-i18n="' + hintKey + '"></div>' +
                '</div>';
        }

        _numberGroup(id, labelKey, hintKey, val, min, max) {
            return '<div class="turnaround-sim-decision-group">' +
                '<label for="' + id + 'Input" data-i18n="' + labelKey + '"></label>' +
                '<input type="number" id="' + id + 'Input" min="' + min + '" max="' + max + '" value="' + val + '" step="1">' +
                '<div class="turnaround-sim-hint" data-i18n="' + hintKey + '"></div>' +
                '</div>';
        }

        _selectGroup(id, labelKey, hintKey, val, options) {
            var opts = '';
            for (var i = 0; i < options.length; i++) {
                var sel = (String(options[i].value) === String(val)) ? ' selected' : '';
                opts += '<option value="' + options[i].value + '"' + sel + ' data-i18n="' + options[i].labelKey + '"></option>';
            }
            return '<div class="turnaround-sim-decision-group">' +
                '<label for="' + id + 'Input" data-i18n="' + labelKey + '"></label>' +
                '<select id="' + id + 'Input">' + opts + '</select>' +
                '<div class="turnaround-sim-hint" data-i18n="' + hintKey + '"></div>' +
                '</div>';
        }

        _attachSliderListeners() {
            var sliders = ['overheadCut', 'workingCapitalEffort', 'payrollCut', 'haircutProposal', 'maturityExtension', 'workforceReduction'];
            var units = { overheadCut: '%', workingCapitalEffort: '%', payrollCut: '%', haircutProposal: '%', maturityExtension: ' mo', workforceReduction: '%' };
            for (var i = 0; i < sliders.length; i++) {
                var sid = sliders[i];
                var slider = document.getElementById(sid + 'Input');
                var display = document.getElementById(sid + 'Display');
                if (slider && display) {
                    (function(s, d, u) {
                        s.addEventListener('input', function() {
                            d.textContent = s.value + u;
                        });
                    })(slider, display, units[sid] || '');
                }
            }
        }

        validateDecisions(decisions) {
            var period = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state.currentPeriod : 1;

            if (period === 1) {
                var oc = document.getElementById('overheadCutInput');
                if (oc) decisions.overheadCut = parseFloat(oc.value);
                var wc = document.getElementById('workingCapitalEffortInput');
                if (wc) decisions.workingCapitalEffort = parseFloat(wc.value);
                var as = document.getElementById('assetSalesTargetInput');
                if (as) decisions.assetSalesTarget = parseFloat(as.value);
                var pc = document.getElementById('payrollCutInput');
                if (pc) decisions.payrollCut = parseFloat(pc.value);

                if (decisions.assetSalesTarget < 0 || decisions.assetSalesTarget > 25) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('asset_warning'), 'warning');
                    return false;
                }
            } else if (period === 2) {
                var hp = document.getElementById('haircutProposalInput');
                if (hp) decisions.haircutProposal = parseFloat(hp.value);
                var da = document.getElementById('dipAmountInput');
                if (da) decisions.dipAmount = parseFloat(da.value);
                var rp = document.getElementById('restrPathInput');
                if (rp) decisions.restrPath = rp.value;
                var me = document.getElementById('maturityExtensionInput');
                if (me) decisions.maturityExtension = parseFloat(me.value);

                if (decisions.dipAmount < 5 || decisions.dipAmount > 25) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('dip_warning'), 'warning');
                    return false;
                }
            } else if (period === 3) {
                var cm = document.getElementById('closMinasInput') || document.getElementById('closeMinasInput');
                if (cm) decisions.closeMinas = parseInt(cm.value);
                var dc = document.getElementById('divestComponentsInput');
                if (dc) decisions.divestComponents = parseInt(dc.value);
                var wr = document.getElementById('workforceReductionInput');
                if (wr) decisions.workforceReduction = parseFloat(wr.value);
                var ci = document.getElementById('capexInvestmentInput');
                if (ci) decisions.capexInvestment = parseFloat(ci.value);
            } else if (period === 4) {
                var rt = document.getElementById('refinancingTargetInput');
                if (rt) decisions.refinancingTarget = parseFloat(rt.value);
                var ec = document.getElementById('ebitdaCommitmentInput');
                if (ec) decisions.ebitdaCommitment = parseFloat(ec.value);
                var cs = document.getElementById('commStrategyInput');
                if (cs) decisions.commStrategy = cs.value;

                if (decisions.refinancingTarget < 50 || decisions.refinancingTarget > 150) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('refinancing_warning'), 'warning');
                    return false;
                }
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var results = { period: period };
            var messages = [];

            if (period === 1) {
                var overheadSaved = (d.overheadCut / 100) * 2;
                var wcRelease = (d.workingCapitalEffort / 100) * 8;
                var realizationRate = d.assetSalesTarget > 15 ? 0.65 : (d.assetSalesTarget > 10 ? 0.75 : 0.85);
                var assetProceeds = d.assetSalesTarget * realizationRate;
                var payrollSaved = (d.payrollCut / 100) * 3;

                var moraleDrop = 0;
                if (d.payrollCut > 20) moraleDrop = 20;
                else if (d.payrollCut > 10) moraleDrop = 10;
                else moraleDrop = 5;

                var valeDrop = 0;
                if (d.payrollCut > 25) valeDrop = 15;
                else if (d.payrollCut > 15) valeDrop = 5;

                ds.monthlyBurn = Math.max(1.5, ds.monthlyBurn - overheadSaved - payrollSaved);
                ds.cash = ds.cash + wcRelease + assetProceeds - ds.monthlyBurn;
                ds.assetValue = Math.max(10, ds.assetValue - d.assetSalesTarget);
                ds.morale = Math.max(10, ds.morale - moraleDrop);
                ds.valeConfidence = Math.max(20, ds.valeConfidence - valeDrop);
                ds.employees = Math.round(ds.employees * (1 - d.payrollCut / 100));
                ds.overheadCosts = ds.overheadCosts * (1 - d.overheadCut / 100);
                ds.ebitda = ds.ebitda + (overheadSaved + payrollSaved) * 12;
                ds.cashRunway = ds.monthlyBurn > 0 ? Math.round((ds.cash / ds.monthlyBurn) * 30) : 999;

                var zImprovement = (overheadSaved + payrollSaved) * 0.08 + wcRelease * 0.02;
                ds.zScore = Math.min(3.5, ds.zScore + zImprovement);

                results.overheadSaved = overheadSaved;
                results.wcRelease = wcRelease;
                results.assetProceeds = assetProceeds;
                results.payrollSaved = payrollSaved;
                results.newBurn = ds.monthlyBurn;
                results.cashAfter = ds.cash;
                results.runwayDays = ds.cashRunway;

                messages.push('Overhead reduced by ' + overheadSaved.toFixed(1) + 'M/month');
                messages.push('Working capital released ' + wcRelease.toFixed(1) + 'M');
                messages.push('Asset sales generated ' + assetProceeds.toFixed(1) + 'M (at ' + Math.round(realizationRate * 100) + '% realization)');
                messages.push('Monthly burn reduced to ' + ds.monthlyBurn.toFixed(1) + 'M');
                messages.push('Cash runway extended to ' + ds.cashRunway + ' days');
                ds.roundActions.push('R1: Cut overhead ' + d.overheadCut + '%, WC ' + d.workingCapitalEffort + '%, sold ' + d.assetSalesTarget + 'M assets, payroll cut ' + d.payrollCut + '%');

            } else if (period === 2) {
                var cashRunwayFactor = Math.min(1, ds.cashRunway / 180);
                var zFactor = Math.min(1, ds.zScore / 2.0);
                var credibility = (cashRunwayFactor + zFactor) / 2;
                var haircutAcceptable = Math.min(55, Math.round(credibility * 50 + 10));
                var haircutActual = Math.min(d.haircutProposal, haircutAcceptable);

                if (d.haircutProposal > haircutAcceptable + 15) {
                    haircutActual = Math.max(0, haircutAcceptable - 10);
                    messages.push('WARNING: Aggressive haircut proposal angered creditors. They countered with only ' + haircutActual + '% reduction.');
                    ds.valeConfidence = Math.max(10, ds.valeConfidence - 10);
                } else if (d.haircutProposal > haircutAcceptable) {
                    haircutActual = haircutAcceptable;
                    messages.push('Creditors negotiated haircut down to ' + haircutActual + '%.');
                } else {
                    messages.push('Creditors accepted the proposed ' + haircutActual + '% haircut.');
                }

                ds.unsecuredDebt = ds.unsecuredDebt * (1 - haircutActual / 100);
                ds.haircutAccepted = haircutActual;

                var dipCost = d.restrPath === 'chapter11' ? 7 : 2;
                var dipInterestAnnual = d.dipAmount * 0.1025;
                ds.dipFinancing = d.dipAmount;
                ds.cash = ds.cash + d.dipAmount - dipCost - ds.monthlyBurn;
                ds.totalDebt = ds.securedDebt + ds.unsecuredDebt + d.dipAmount;
                ds.restructuringPath = d.restrPath;

                if (d.restrPath === 'chapter11') {
                    ds.valeConfidence = Math.max(10, ds.valeConfidence - 15);
                    ds.morale = Math.max(10, ds.morale - 10);
                    messages.push('Chapter 11 filed. Automatic stay in effect. VALE confidence dropped — public process created uncertainty.');
                } else {
                    ds.valeConfidence = Math.min(100, ds.valeConfidence + 5);
                    messages.push('Out-of-court restructuring initiated. Private process preserved VALE confidence.');
                }

                ds.ebitda = ds.ebitda - dipInterestAnnual;
                ds.cashRunway = ds.monthlyBurn > 0 ? Math.round((ds.cash / ds.monthlyBurn) * 30) : 999;
                var zBoost = (haircutActual / 100) * 0.5 + (d.dipAmount / 25) * 0.2;
                ds.zScore = Math.min(3.5, ds.zScore + zBoost);

                results.haircutAccepted = haircutActual;
                results.dipProceeds = d.dipAmount;
                results.restrCost = dipCost;
                results.cashAfter = ds.cash;
                results.newDebt = ds.totalDebt;
                results.runwayDays = ds.cashRunway;

                messages.push('DIP financing of ' + d.dipAmount + 'M secured (cost: ' + dipCost + 'M)');
                messages.push('Total debt now ' + ds.totalDebt.toFixed(1) + 'M');
                ds.roundActions.push('R2: Haircut ' + haircutActual + '%, DIP ' + d.dipAmount + 'M, path: ' + d.restrPath + ', ext: ' + d.maturityExtension + 'mo');

            } else if (period === 3) {
                var revLost = 0;
                var costSaved = 0;
                var oneTimeCost = 0;
                var proceeds = 0;

                if (d.closeMinas === 1 || d.closeMinas === '1') {
                    ds.minasOpen = false;
                    revLost += 5;
                    costSaved += 6;
                    oneTimeCost += 4;
                    ds.employees = Math.max(200, ds.employees - 180);
                    ds.morale = Math.max(10, ds.morale - 8);
                    messages.push('Minas Gerais plant closed. 180 employees laid off. Annual savings: 6M. One-time cost: 4M.');
                }

                if (d.divestComponents === 1 || d.divestComponents === '1') {
                    ds.componentsOwned = false;
                    var salePrice = 6;
                    revLost += 8;
                    costSaved += 8.2;
                    proceeds += salePrice;
                    ds.employees = Math.max(200, ds.employees - 120);
                    messages.push('Components division divested for ' + salePrice.toFixed(1) + 'M. Eliminated negative-margin business.');
                }

                var wfCut = d.workforceReduction / 100;
                var additionalCuts = Math.round(ds.employees * wfCut);
                var severanceCost = additionalCuts * 0.015;
                var laborSaved = additionalCuts * 0.025;
                ds.employees = Math.max(200, ds.employees - additionalCuts);
                oneTimeCost += severanceCost;
                costSaved += laborSaved;

                if (d.workforceReduction > 25) {
                    ds.morale = Math.max(5, ds.morale - 20);
                    ds.valeConfidence = Math.max(10, ds.valeConfidence - 10);
                    messages.push('WARNING: Aggressive workforce cuts damaging morale and making VALE nervous about delivery capacity.');
                } else if (d.workforceReduction > 15) {
                    ds.morale = Math.max(10, ds.morale - 10);
                    messages.push('Significant workforce reduction. Morale impacted but manageable.');
                } else {
                    ds.morale = Math.max(10, ds.morale - 5);
                }

                var capexBenefit = d.capexInvestment * 0.8;
                ds.cash = ds.cash + proceeds - oneTimeCost - d.capexInvestment - ds.monthlyBurn;
                ds.revenue = ds.revenue - revLost;
                ds.ebitda = ds.ebitda + (costSaved - revLost * 0.3) * 1 + capexBenefit;
                ds.overheadCosts = Math.max(5, ds.overheadCosts - costSaved);
                ds.cashRunway = ds.monthlyBurn > 0 ? Math.round((ds.cash / ds.monthlyBurn) * 30) : 999;

                var zBoost3 = costSaved * 0.05 + capexBenefit * 0.03 - revLost * 0.02;
                ds.zScore = Math.min(3.5, ds.zScore + zBoost3);

                if (d.capexInvestment > 0) {
                    ds.valeConfidence = Math.min(100, ds.valeConfidence + d.capexInvestment * 3);
                    messages.push('Capex investment of ' + d.capexInvestment + 'M improving core operations efficiency. VALE confidence boosted.');
                }

                results.revenueLost = revLost;
                results.costSaved = costSaved;
                results.oneTimeCosts = oneTimeCost;
                results.proceeds = proceeds;
                results.cashAfter = ds.cash;
                results.employeesRemaining = ds.employees;
                results.runwayDays = ds.cashRunway;

                messages.push('Employees remaining: ' + ds.employees);
                ds.roundActions.push('R3: Minas=' + (ds.minasOpen ? 'open' : 'closed') + ', Components=' + (ds.componentsOwned ? 'kept' : 'divested') + ', WF cut ' + d.workforceReduction + '%, Capex ' + d.capexInvestment + 'M');

            } else if (period === 4) {
                var actualEbitda = ds.ebitda;
                var debtToEbitda = actualEbitda > 0 ? ds.totalDebt / actualEbitda : 99;
                var credibilityGap = Math.abs(d.ebitdaCommitment - actualEbitda);
                var credibilityScore = 0;

                if (credibilityGap < 2) {
                    credibilityScore = 90;
                    messages.push('EBITDA commitment aligns well with demonstrated performance. Creditors find the plan credible.');
                } else if (credibilityGap < 5) {
                    credibilityScore = 60;
                    messages.push('EBITDA commitment is somewhat ambitious relative to current performance. Creditors cautiously optimistic.');
                } else {
                    credibilityScore = 30;
                    messages.push('WARNING: Large gap between committed EBITDA and actual performance. Creditors skeptical.');
                    ds.valeConfidence = Math.max(10, ds.valeConfidence - 10);
                }

                if (d.commStrategy === 'transparent') {
                    credibilityScore += 15;
                    ds.morale = Math.min(100, ds.morale + 10);
                    ds.valeConfidence = Math.min(100, ds.valeConfidence + 10);
                    messages.push('Transparent communication builds trust with all stakeholders.');
                } else if (d.commStrategy === 'optimistic') {
                    credibilityScore -= 10;
                    ds.morale = Math.min(100, ds.morale + 5);
                    messages.push('Optimistic messaging boosts short-term morale but creditors see through it.');
                } else {
                    credibilityScore += 5;
                    ds.valeConfidence = Math.min(100, ds.valeConfidence + 5);
                    messages.push('Conservative projections build creditor confidence but may limit ambition.');
                }

                var refinancingFeasible = debtToEbitda < 6 && ds.cash > 5 && credibilityScore > 50;
                ds.totalDebt = refinancingFeasible ? d.refinancingTarget : ds.totalDebt;
                ds.cashRunway = ds.monthlyBurn > 0 ? Math.round((ds.cash / ds.monthlyBurn) * 30) : 999;

                var finalZ = ds.zScore + credibilityScore * 0.005;
                ds.zScore = Math.min(3.5, finalZ);

                if (refinancingFeasible) {
                    messages.push('Refinancing successful! Debt restructured to ' + d.refinancingTarget + 'M.');
                } else {
                    messages.push('Refinancing NOT feasible at current metrics. Existing debt structure remains.');
                    if (debtToEbitda >= 6) messages.push('Debt-to-EBITDA ratio of ' + debtToEbitda.toFixed(1) + 'x is too high for refinancing.');
                    if (ds.cash <= 5) messages.push('Cash position too weak to support refinancing.');
                }

                results.credibilityScore = credibilityScore;
                results.debtToEbitda = debtToEbitda;
                results.refinancingFeasible = refinancingFeasible;
                results.finalDebt = ds.totalDebt;
                results.cashAfter = ds.cash;
                results.runwayDays = ds.cashRunway;

                ds.roundActions.push('R4: Refi target ' + d.refinancingTarget + 'M, EBITDA commit ' + d.ebitdaCommitment + 'M, strategy: ' + d.commStrategy);
            }

            ds.cashHistory.push(Math.round(ds.cash * 10) / 10);
            ds.zScoreHistory.push(Math.round(ds.zScore * 100) / 100);
            ds.ebitdaHistory.push(Math.round(ds.ebitda * 10) / 10);
            ds.burnHistory.push(Math.round(ds.monthlyBurn * 10) / 10);

            results.cash = ds.cash;
            results.zScore = ds.zScore;
            results.ebitda = ds.ebitda;
            results.messages = messages;

            var resultsPanel = document.getElementById('resultsPanel');
            var resultsText = document.getElementById('resultsText');
            if (resultsPanel && resultsText) {
                resultsPanel.style.display = 'block';
                resultsText.innerHTML = messages.map(function(m) { return '<p>' + m + '</p>'; }).join('');
            }

            var alertEl = document.getElementById('alertText');
            if (alertEl) {
                if (ds.cash < 5) {
                    alertEl.innerHTML = 'CRITICAL: Cash below €5M. Insolvency imminent without immediate action.';
                } else if (ds.cashRunway < 60) {
                    alertEl.innerHTML = 'WARNING: Only ' + ds.cashRunway + ' days of cash remaining.';
                } else if (ds.zScore > 1.81) {
                    alertEl.innerHTML = 'IMPROVING: Z-Score has moved to gray zone (' + ds.zScore.toFixed(2) + '). Continue stabilization efforts.';
                } else {
                    alertEl.innerHTML = 'DISTRESS: Z-Score at ' + ds.zScore.toFixed(2) + '. Still in danger zone.';
                }
            }

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
                self._buildDecisionInputs({ currentPeriod: state.currentPeriod + 1, decisions: state.decisions, domainState: ds });
                if (window.mySimulation && window.mySimulation.adapter && window.mySimulation.adapter.getTranslations) {
                    var trans = window.mySimulation.adapter.getTranslations();
                    var lang = (window.mySimulation && (window.mySimulation.language || window.mySimulation.currentLanguage)) || (typeof document !== 'undefined' && document.documentElement && document.documentElement.lang) || 'en';
                    if (trans && trans[lang]) {
                        var els = document.querySelectorAll('[data-i18n]');
                        for (var e = 0; e < els.length; e++) {
                            var key = els[e].getAttribute('data-i18n');
                            if (trans[lang][key]) els[e].textContent = trans[lang][key];
                        }
                    }
                }
            }, 600);

            return results;
        }

